---
const { href, label } = Astro.props;
const pathname = Astro.url.pathname;
const exact = pathname === href;
const section = href !== '/' && pathname.startsWith(`${href}/`);
---

<a
  href={href}
  class:list={{ active: exact || section }}
  aria-current={exact ? 'page' : undefined}
>
  {label}
</a>
